const body = $input.first().json.body || $input.first().json;
const question = body.question || '';
const companyId = body.companyId || null;
const inspectionId = body.inspectionId || null;
const history = Array.isArray(body.history) ? body.history : [];
const ctx = body.enrichedContext || {};

const systemPrompt = `Sei un consulente HSE esperto italiano per il software FedShield. Rispondi in italiano citando sempre il riferimento normativo esatto (D.Lgs 81/08, Reg. CE 852/2004, D.Lgs 231/01, ecc.). Per ogni non conformita rilevata suggerisci gravita (1-4), sanzionabilita (si/no) e servizio consigliato. NON inventare norme: se non sei sicuro dichiaralo. Risposte max 300 parole.`;

const companyLine = ctx.company ? `Nome: ${ctx.company.name}, ATECO: ${ctx.company.atecoCode}, Citta: ${ctx.company.city || 'N/D'}, Rischio: ${ctx.company.riskLevel || 'N/D'}` : 'N/D';
const trainingLine = ctx.training ? JSON.stringify(ctx.training).slice(0, 1500) : 'N/D';
const inspectionLine = ctx.inspection ? `Titolo: ${ctx.inspection.title}, Stato: ${ctx.inspection.status}` : 'Nessun audit attivo';
const historyLines = history.slice(-5).map((h) => `${h.role || 'user'}: ${h.content || h.message || ''}`).join('\n');

const userPrompt = `CONTESTO AZIENDA:\n${companyLine}\n\nSTATO FORMAZIONE:\n${trainingLine}\n\nAUDIT IN CORSO:\n${inspectionLine}\n\nSTORICO RECENTE:\n${historyLines}\n\nDOMANDA CONSULENTE: ${question}`;

return [{ json: { systemPrompt, userPrompt, _meta: { companyId, inspectionId, hasContext: !!ctx.company } } }];

const aiResp = $input.first().json || {};
const choices = aiResp.choices || [];
const content = choices[0] && choices[0].message ? (choices[0].message.content || '') : '';
const answer = String(content).trim() || 'Il modello AI non ha prodotto una risposta utilizzabile.';
return [{ json: { answer, source: 'n8n', citations: [], timestamp: new Date().toISOString() } }];
